"""Projects and thread workspace schema."""

from __future__ import annotations

from octop.infra.db.migrate.introspect import (
    _ensure_column,
    _table_exists,
)
from octop.infra.db.pool import DatabasePool

_PROJECT_THREAD_COLUMNS = (
    ("project_id", "TEXT"),
    ("workspace_kind", "TEXT"),
    ("workspace_dir", "TEXT"),
)


def _ensure_projects_schema(db: DatabasePool) -> None:
    """v29: projects table plus thread ownership columns (idempotent)."""
    if _table_exists(db, "users"):
        identity = (
            "INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY"
            if db.dialect == "postgresql"
            else "INTEGER PRIMARY KEY AUTOINCREMENT"
        )
        with db.connect() as conn:
            conn.execute(
                "CREATE TABLE IF NOT EXISTS projects ("
                f"id {identity}, "
                "project_id TEXT NOT NULL UNIQUE, "
                "user_id INTEGER NOT NULL REFERENCES users(id) ON DELETE CASCADE, "
                "name TEXT NOT NULL, "
                "root_dir TEXT, "
                "is_default INTEGER NOT NULL DEFAULT 0, "
                "origin TEXT NOT NULL DEFAULT 'manual', "
                "created_at INTEGER NOT NULL, "
                "updated_at INTEGER NOT NULL)"
            )
            conn.execute(
                "CREATE UNIQUE INDEX IF NOT EXISTS idx_projects_default_per_user "
                "ON projects (user_id) WHERE is_default = 1"
            )
            conn.execute(
                "CREATE INDEX IF NOT EXISTS idx_projects_user_updated "
                "ON projects (user_id, updated_at DESC)"
            )
    if _table_exists(db, "threads"):
        for column, definition in _PROJECT_THREAD_COLUMNS:
            _ensure_column(db, "threads", column, definition)
        with db.connect() as conn:
            conn.execute(
                "CREATE INDEX IF NOT EXISTS idx_threads_project "
                "ON threads (project_id, last_active DESC)"
            )
